import { customAlphabet } from 'nanoid';
import { prisma } from '../lib/db';  // We'll create this next

const alphabet = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
const generateShortCode = customAlphabet(alphabet, 7); // ~3.5 trillion combos

export async function createUniqueShortCode(): Promise<string> {
  let shortCode: string;
  let attempts = 0;
  const maxAttempts = 10; // safety net

  do {
    shortCode = generateShortCode();
    attempts++;

    const existing = await prisma.shortLink.findUnique({
      where: { shortCode },
    });

    if (!existing) {
      return shortCode;
    }

    if (attempts >= maxAttempts) {
      throw new Error('Failed to generate unique short code after max attempts');
    }
  } while (true);
}